properties.query:
let alertWindow = 10m;
let burstWindow = 5m;
let burstThreshold = 50;
let TrustedSources = _GetWatchlist('Trusted_TI_Source_List') | project SourceId;
let UnknownSource =
    UAVThreatIntel_CL
    | where TimeGenerated > ago(alertWindow)
    | where Source !in (TrustedSources)
    | summarize Count=count(), FirstSeen=min(TimeGenerated)
        by Source
    | extend TriggerReason = strcat("TI_비신뢰_소스_", Source)
    | extend Severity = "High";
let IocBurst =
    UAVThreatIntel_CL
    | where TimeGenerated > ago(burstWindow)
    | summarize IocCount=count() by Source, bin(TimeGenerated, burstWindow)
    | where IocCount > burstThreshold
    | extend TriggerReason = strcat("TI_IOC_버스트_", Source, "_", tostring(IocCount), "건")
    | extend Severity = "Medium";
union
    (UnknownSource | project FirstSeen, Source, TriggerReason, Severity),
    (IocBurst | project FirstSeen=TimeGenerated, Source, TriggerReason, Severity)
| extend IncidentType = "S15_TI_소스_오염"
| order by Severity desc, FirstSeen asc
